function generate_problems_testing_eig2to3(n_samples, seed, out_dir)
%GENERATE_PROBLEMS_TESTING_EIG2TO3  Generate parabolic-IBVP problem instances
%(Eq. 1.4, same problem_instance_*.mat schema as export_matlab_problem.py)
%directly in MATLAB, ready for solve_reference_pde_batch.m.
%
% This is a deliberately DIFFERENT test distribution from
% problems_training/problems_testing (which are generated by
% export_matlab_problem.py with eig_low=1, eig_high=2, and b1,b2,c,beta,
% f,g,h each drawn i.i.d. Normal(0, amplitude) with amplitude 0.6 for
% b1/b2/c, 0.8 for beta, and 1.0 for f/g/h):
%
%   - a_ij eigenvalues drawn from [2, 3] instead of [1, 2] (stiffer,
%     still-elliptic diffusion tensor)
%   - g is fixed to 0 (zero initial condition, Eq. 1.4b), as in training
%   - b1, b2, c, beta, f, h are still Normal(0, amplitude), but with a
%     WIDER range (double the original amplitude): 1.2 for b1/b2/c, 1.6
%     for beta, 2.0 for f/h  (paper Sec. 3.5 OOD set)
%
% The point is to probe generalization (FEM vs Green's-function vs
% 2D-CNN, see benchmark_compare.py) to both a stiffer/more anisotropic
% diffusion tensor and larger-magnitude coefficients/forcing/boundary
% data, without touching problems_training or problems_testing.
%
% Usage:
%   >> generate_problems_testing_eig2to3()
%       100 samples, seed 9000, written to ../dataset/main/matlab_problems/ood
%   >> generate_problems_testing_eig2to3(100, 9000, fullfile('..','dataset','main','matlab_problems','ood'))
%
% Each instance is written as problem_instance_NNNNN.mat with fields
% radius, center, T, b1, b2, c, beta, f, h, g, a11_corners, a12_corners,
% a22_corners -- exactly the schema solve_reference_pde_batch.m expects
% (see also run_problems_ood.m).

if nargin < 1 || isempty(n_samples), n_samples = 100; end
if nargin < 2 || isempty(seed),      seed = 9000; end
if nargin < 3 || isempty(out_dir),   out_dir = fullfile('..', 'dataset', 'main', 'matlab_problems', 'ood'); end

radius = 1.0;
center = [0.0, 0.0];
T = 1.0;
eig_low = 2.0;
eig_high = 3.0;

% Normal(0, amplitude) for every coefficient, same family as
% export_matlab_problem.py, just a wider (2x) amplitude/range.
amp_b1 = 1.2; amp_b2 = 1.2; amp_c = 1.2; amp_beta = 1.6;
amp_f = 2.0; amp_g = 2.0; amp_h = 2.0;

if ~exist(out_dir, 'dir'), mkdir(out_dir); end

for i = 0:n_samples - 1
    rng(seed + i, 'twister');  % reproducible per-instance seed, mirrors
                                % export_matlab_problem.py's seed+i pattern

    [a11_corners, a12_corners, a22_corners] = draw_a_ij_quadrants(eig_low, eig_high);

    b1   = draw_normal(0.0, amp_b1);
    b2   = draw_normal(0.0, amp_b2);
    c    = draw_normal(0.0, amp_c);
    beta = draw_normal(0.0, amp_beta);
    f    = draw_normal(0.0, amp_f);
    draw_normal(0.0, amp_g);  % consumed+discarded (keeps the RNG stream of the old random-g OOD set)
    g    = 0.0;               % zero initial condition u(x,0) = 0 (Eq. 1.4b)
    h    = draw_normal(0.0, amp_h);

    out_path = fullfile(out_dir, sprintf('problem_instance_%05d.mat', i));
    save(out_path, 'radius', 'center', 'T', 'b1', 'b2', 'c', 'beta', 'f', 'h', 'g', ...
        'a11_corners', 'a12_corners', 'a22_corners');

    fprintf('[%d/%d] wrote %s\n', i + 1, n_samples, out_path);
    fprintf(['    a_ij corners: TL=[[%.3f,%.3f],[%.3f,%.3f]]  TR=[[%.3f,%.3f],[%.3f,%.3f]]  ' ...
             'BL=[[%.3f,%.3f],[%.3f,%.3f]]  BR=[[%.3f,%.3f],[%.3f,%.3f]]\n'], ...
        a11_corners(1), a12_corners(1), a12_corners(1), a22_corners(1), ...
        a11_corners(2), a12_corners(2), a12_corners(2), a22_corners(2), ...
        a11_corners(3), a12_corners(3), a12_corners(3), a22_corners(3), ...
        a11_corners(4), a12_corners(4), a12_corners(4), a22_corners(4));
    fprintf('    b1=%.4f b2=%.4f c=%.4f beta=%.4f f=%.4f h=%.4f g=%.4f\n', ...
        b1, b2, c, beta, f, h, g);
end

fprintf('\ndone: wrote %d instance(s) to %s\n', n_samples, out_dir);

end


function [a11_corners, a12_corners, a22_corners] = draw_a_ij_quadrants(eig_low, eig_high)
% Four independent constant, symmetric, elliptic 2x2 a_ij matrices
% (Eq. 1.1), one per quadrant of the disk split by x=center_x, y=center_y
% (order TL,TR,BL,BR -- matches export_matlab_problem.py's
% draw_a_ij_quadrants), eigenvalues in [eig_low, eig_high].
a11_corners = zeros(1, 4);
a12_corners = zeros(1, 4);
a22_corners = zeros(1, 4);
for k = 1:4
    [a11, a12, a22] = draw_a_ij(eig_low, eig_high);
    a11_corners(k) = a11;
    a12_corners(k) = a12;
    a22_corners(k) = a22;
end
end


function [a11, a12, a22] = draw_a_ij(eig_low, eig_high)
lam1 = eig_low + (eig_high - eig_low) * rand();
lam2 = eig_low + (eig_high - eig_low) * rand();
th = pi * rand();
ct = cos(th); st = sin(th);
a11 = lam1 * ct^2 + lam2 * st^2;
a22 = lam1 * st^2 + lam2 * ct^2;
a12 = (lam1 - lam2) * st * ct;
end


function x = draw_normal(mu, sigma)
x = mu + sigma * randn();
end
